def _csv_table_project_emit(rows: list[CsvRow], columns: list[int]) -> int:
    count: int = 0
    for row in rows:
        projected: CsvRow = csv_project_row(row, columns)
        write_stdout_bytes((csv_stream_row_json(projected) + '\n').encode('utf-8'))
        count += 1
    return count

def csv_table_project_file(path: str, columns: list[int], size: int) -> int:
    if size <= 0:
        raise ValueError
    for column in columns:
        if column < 0:
            raise ValueError
    utf8 = utf8_decoder_new()
    csv = csv_decoder_new()
    count: int = 0
    for chunk in file_chunks(path, size):
        rows = csv_decode_feed(csv, utf8_decode_feed(utf8, chunk))
        count += _csv_table_project_emit(rows, columns)
    tail = csv_decode_feed(csv, utf8_decode_finish(utf8))
    count += _csv_table_project_emit(tail, columns)
    final = csv_decode_finish(csv)
    count += _csv_table_project_emit(final, columns)
    return count

def csv_table_group_file(path: str, key_column: int, value_column: int, size: int) -> str:
    if size <= 0 or key_column < 0 or value_column < 0:
        raise ValueError
    utf8 = utf8_decoder_new()
    csv = csv_decoder_new()
    groups = csv_groups_new()
    for chunk in file_chunks(path, size):
        rows = csv_decode_feed(csv, utf8_decode_feed(utf8, chunk))
        csv_groups_add(groups, rows, key_column, value_column)
    tail = csv_decode_feed(csv, utf8_decode_finish(utf8))
    csv_groups_add(groups, tail, key_column, value_column)
    final = csv_decode_finish(csv)
    csv_groups_add(groups, final, key_column, value_column)
    return csv_groups_render(groups)

def _csv_table_columns(text: str) -> list[int]:
    columns: list[int] = []
    if text == '':
        return columns
    for token in text.split(','):
        column: int = parse_int64_decimal(token)
        if column < 0:
            raise ValueError
        columns.append(column)
    return columns

def main() -> int:
    if len(sys.argv) != 5 and len(sys.argv) != 6:
        print('usage: csv_table project INPUT COLUMNS SIZE | group INPUT KEY_COLUMN VALUE_COLUMN SIZE', file=sys.stderr)
